/**
 * Gherkin map generator (TASK-277, T-QA-02; TEST-STRATEGY section 6). The committed
 * docs/05-quality/tests/gherkin-test-map.md is regenerated byte-identically from the story files plus qa-lead's suite
 * assignments; stories whose Gherkin changed after the map was classified fail the generator by story ID.
 */
import { existsSync, linkSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { afterEach, describe, expect, it } from '@jest/globals';

import { findRepoRoot } from '../test-support/process.js';
import {
  ASSIGNMENTS_PATH,
  OUTLINE_SUFFIX,
  buildRows,
  firstDifference,
  loadAssignments,
  main,
  parseAssignments,
  renderMap,
} from './gen-gherkin-map.mjs';
import { MAP_PATHS, MapError, loadStories, parseGherkinMap, type Story } from './lib/test-ids.mjs';

const repoRoot = findRepoRoot();
const committedMap = readFileSync(join(repoRoot, ...MAP_PATHS.gherkin.split('/')), 'utf8');

/**
 * Must stories whose Gherkin gained scenarios that qa-lead has not classified yet. Empty since map v1.1 (D-QA-016
 * classified the 13 scenarios appended by D-065): the committed map must equal the generator output for the real story
 * files. A future story edit that adds scenarios fails the equality and drift tests below until qa-lead classifies them;
 * listing the story here is only a temporary, reviewed bridge (the ratchet test fails while it names a story that no
 * longer drifts).
 */
const KNOWN_DRIFT: string[] = [];

/** The story model of the real repository, with the drifted stories' scenarios taken from the committed map rows. */
function storiesAsMapped(): Story[] {
  const rows = parseGherkinMap(committedMap);
  return loadStories(repoRoot, (dir) => readdirSync(dir)).map((story) =>
    KNOWN_DRIFT.includes(story.id)
      ? {
          ...story,
          scenarios: rows
            .filter((row) => row.story === story.id)
            .map((row, index) => ({
              index: index + 1,
              title: row.title.endsWith(OUTLINE_SUFFIX) ? row.title.slice(0, -OUTLINE_SUFFIX.length) : row.title,
              outline: row.title.endsWith(OUTLINE_SUFFIX),
              liveSandbox: !row.g3,
            })),
        }
      : story,
  );
}

describe('gen-gherkin-map against the real repository', () => {
  const assignments = loadAssignments(repoRoot);

  it('renders the committed map byte-identically (story files plus suite assignments)', () => {
    const text = renderMap(buildRows(storiesAsMapped(), assignments), assignments.meta);
    expect(firstDifference(committedMap, text)).toBe(0);
    expect(text).toBe(committedMap);
  });

  it('counts 218 Must stories and 1612 scenarios, 1606 of them G3-counted', () => {
    const rows = buildRows(storiesAsMapped(), assignments);
    expect(new Set(rows.map((r) => r.story.id)).size).toBe(218);
    expect(rows).toHaveLength(1612);
    expect(rows.filter((r) => r.g3)).toHaveLength(1606);
  });

  it('drift guard: exactly the known drifted stories need qa-lead classification (ratchet)', () => {
    const stories = loadStories(repoRoot, (dir) => readdirSync(dir));
    let message = '';
    try {
      buildRows(stories, assignments);
    } catch (error) {
      expect(error).toBeInstanceOf(MapError);
      message = (error as Error).message;
    }
    const named = [...message.matchAll(/(US-\d{3}) \(/g)].map((m) => m[1]);
    expect(named).toEqual(KNOWN_DRIFT);
  });

  it('every Must story of the story files has an assignment entry', () => {
    const must = loadStories(repoRoot, (dir) => readdirSync(dir)).filter((s) => s.moscow === 'Must');
    expect(must.filter((s) => assignments.stories[s.id] === undefined).map((s) => s.id)).toEqual([]);
    expect(Object.keys(assignments.stories)).toHaveLength(must.length);
  });
});

describe('gen-gherkin-map on a synthetic repository', () => {
  const temps: string[] = [];
  afterEach(() => {
    for (const dir of temps.splice(0)) rmSync(dir, { recursive: true, force: true });
  });

  const STORY_FILE = [
    '# EPIC-01 — Sample',
    '',
    '## Story summary',
    '| ID | Title | MS | MoSCoW | Size | Depends on | Linked REQs | DC |',
    '|---|---|---|---|---|---|---|---|',
    '| US-001 | First | M0 | Must | S | - | REQ-1 | DC |',
    '| US-002 | Second | M0 | Should | S | - | REQ-2 |  |',
    '| US-003 | Third | M1 | Must | S | - | REQ-3 |  |',
    '',
    '## Stories',
    '',
    '### US-001 — First',
    '```gherkin',
    'Feature: First',
    '  # a comment line',
    '  Scenario: Plain one',
    '    Given x',
    '  Scenario Outline: Rows of <n>',
    '    Examples:',
    '      | n |',
    '      | 1 |',
    '```',
    '```text',
    'Scenario: not a scenario (not gherkin)',
    '```',
    '',
    '### US-002 — Second',
    '```gherkin',
    '  Scenario: Should story scenario',
    '```',
    '',
    '### US-003 — Third',
    '```gherkin',
    '  Scenario: Third one',
    '  @live-sandbox',
    '  Scenario: Live one (COND-SANDBOX-DEMO)',
    '```',
    '',
  ].join('\n');

  const ASSIGNMENTS = {
    meta: { version: '1.0', date: '2026-11-12', owner: 'qa-lead', stories_version: '1.3' },
    suite_lanes: { unit: 'A', api: 'B', 'contract-live': 'opt-in' },
    stories: {
      'US-001': { scenarios: 2, default: 'unit', overrides: { '02': 'api' } },
      'US-003': { scenarios: 2, default: 'api', overrides: { '02': 'contract-live' } },
    },
  };

  function makeRoot(assignments: unknown = ASSIGNMENTS): string {
    const root = mkdtempSync(join(tmpdir(), 'gen-gherkin-map-'));
    temps.push(root);
    mkdirSync(join(root, 'docs', '01-requirements', 'stories'), { recursive: true });
    mkdirSync(join(root, 'docs', '05-quality', 'tests'), { recursive: true });
    writeFileSync(join(root, 'docs', '01-requirements', 'stories', 'EPIC-01-sample.md'), STORY_FILE);
    writeFileSync(join(root, ...ASSIGNMENTS_PATH.split('/')), JSON.stringify(assignments));
    return root;
  }

  function run(argv: string[]): { code: number; out: string[]; err: string[] } {
    const out: string[] = [];
    const err: string[] = [];
    const code = main(argv, { out: (l) => out.push(l), err: (l) => err.push(l) });
    return { code, out, err };
  }

  it('writes Must rows with DC, outline suffix, overrides, lanes and the live-sandbox G3 exclusion', () => {
    const root = makeRoot();
    expect(run(['--root', root]).code).toBe(0);
    const text = readFileSync(join(root, ...MAP_PATHS.gherkin.split('/')), 'utf8');
    expect(text).toContain('| AT-US-001-01 | US-001 (DC) | Plain one | `unit` | A | yes |\n');
    expect(text).toContain(`| AT-US-001-02 | US-001 (DC) | Rows of <n>${OUTLINE_SUFFIX} | \`api\` | B | yes |\n`);
    expect(text).toContain(
      '| AT-US-003-02 | US-003 | Live one (COND-SANDBOX-DEMO) | `contract-live` | opt-in | no (COND-SANDBOX-DEMO) |\n',
    );
    expect(text).not.toContain('US-002');
    expect(text).not.toContain('not a scenario');
    expect(text).toContain('- Must stories: 2; Must scenarios: 4 (3 counted for G3 AC coverage, 1 `@live-sandbox`).');
    expect(text).toContain('| `api` | 2 | B |\n| `unit` | 1 | A |\n| `contract-live` | 1 | opt-in |\n');
    expect(text).toContain(
      '| EPIC-01 | 2 | 4 |\n\n\n## EPIC-01 ([stories/EPIC-01-sample.md](../../01-requirements/stories/EPIC-01-sample.md))\n',
    );
    expect(parseGherkinMap(text).map((r) => r.id)).toEqual(['AT-US-001-01', 'AT-US-001-02', 'AT-US-003-01', 'AT-US-003-02']);
  });

  it('--check exits 0 when up to date and 1 with the first differing line otherwise', () => {
    const root = makeRoot();
    expect(run(['--root', root]).code).toBe(0);
    expect(run(['--root', root, '--check'])).toEqual({ code: 0, out: ['quality:gherkin-map: up to date'], err: [] });
    const path = join(root, ...MAP_PATHS.gherkin.split('/'));
    writeFileSync(path, readFileSync(path, 'utf8').replace('Plain one', 'Edited'));
    const result = run(['--root', root, '--check']);
    expect(result.code).toBe(1);
    expect(result.err.join('\n')).toMatch(/differs from the generated one at line \d+/);
    expect(readFileSync(path, 'utf8')).toContain('Edited');
  });

  it('fails naming every story qa-lead must classify (missing entry, changed scenario count, stale entry)', () => {
    const root = makeRoot({
      ...ASSIGNMENTS,
      stories: { 'US-001': { scenarios: 1, default: 'unit' }, 'US-009': { scenarios: 1, default: 'unit' } },
    });
    const result = run(['--root', root]);
    expect(result.code).toBe(1);
    const message = result.err.join('\n');
    expect(message).toContain('US-001 (2 scenarios in the story file, 1 classified)');
    expect(message).toContain('US-003 (not classified)');
    expect(message).toContain('US-009 (classified but not a Must story)');
  });

  it('rejects malformed assignments and usage errors', () => {
    expect(() => parseAssignments({ meta: {}, suite_lanes: {}, stories: {} })).toThrow(MapError);
    expect(() =>
      parseAssignments({ ...ASSIGNMENTS, stories: { 'US-001': { scenarios: 2, default: 'unit', overrides: { '03': 'api' } } } }),
    ).toThrow(/not a scenario number/);
    expect(() => parseAssignments({ ...ASSIGNMENTS, stories: { 'US-001': { scenarios: 2, default: 'nope' } } })).toThrow(/not a suite/);
    expect(run(['--bogus']).code).toBe(2);
    expect(run(['--root']).code).toBe(2);
  });

  it('prints a repository-controlled key on one cleaned line, so it cannot start a workflow command (PR35-SEC-03)', () => {
    const root = makeRoot({
      ...ASSIGNMENTS,
      stories: { 'US-001\n::error::forged\r::warning::x\u2028y': { scenarios: 1, default: 'unit' } },
    });
    const result = run(['--root', root]);
    expect(result.code).toBe(1);
    expect(result.err).toHaveLength(1);
    expect([...(result.err[0] ?? '')].filter((ch) => ch === '\n' || ch === '\r' || ch === '\u2028')).toEqual([]);
    expect(result.err[0]).toContain('US-001 ::error::forged ::warning::x y');
  });

  it('writes --out only inside the root and outside the evidence tree, replacing a hard link instead of writing through it', () => {
    const root = makeRoot();
    expect(run(['--root', root, '--out', join(root, '..', 'outside-map.md')]).code).toBe(2);
    expect(run(['--root', root, '--out', join(root, 'docs', '05-quality', 'tests', 'runs', 'map.md')]).code).toBe(2);
    expect(existsSync(join(root, 'docs', '05-quality', 'tests', 'runs'))).toBe(false);
    writeFileSync(join(root, 'victim.md'), 'keep');
    linkSync(join(root, 'victim.md'), join(root, 'copy.md'));
    expect(run(['--root', root, '--out', join(root, 'copy.md')]).code).toBe(0);
    expect(readFileSync(join(root, 'victim.md'), 'utf8')).toBe('keep');
    expect(readFileSync(join(root, 'copy.md'), 'utf8')).toContain('| AT-US-001-01 |');
  });

  it('firstDifference reports 1-based line numbers', () => {
    expect(firstDifference('a\nb\n', 'a\nb\n')).toBe(0);
    expect(firstDifference('a\nb\n', 'a\nc\n')).toBe(2);
    expect(firstDifference('a\n', 'a\nb\n')).toBe(2);
  });
});
